import{_ as a,c as e,o as d,a2 as r}from"./chunks/framework.BKNXJ1nb.js";const n=JSON.parse('{"title":"声音积木","description":"","frontmatter":{},"headers":[],"relativePath":"scratch-book-preview/3.声音积木.md","filePath":"scratch-book-preview/3.声音积木.md"}'),o={name:"scratch-book-preview/3.声音积木.md"};function h(l,t,c,s,b,i){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="声音积木" tabindex="-1">声音积木 <a class="header-anchor" href="#声音积木" aria-label="Permalink to &quot;声音积木&quot;">​</a></h1><p>声音积木是紫红色的，一共 9 块。它们负责让角色出声：播放或停止声音、调节音量、给声音加音调和左右平衡这类音效。在&quot;声音&quot;标签页里选好声音之后，用这些积木控制它什么时候响、响多大声、什么音色。</p><h2 id="_1-播放声音-喵-v-等待播完" tabindex="-1">1. 播放声音 [喵 v] 等待播完 <a class="header-anchor" href="#_1-播放声音-喵-v-等待播完" aria-label="Permalink to &quot;1. 播放声音 [喵 v] 等待播完&quot;">​</a></h2><pre class="blocks"><code>播放声音 [喵 v] 等待播完</code></pre><p>选中的声音从头播到尾，脚本停在原地等它播完，才继续下一行。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>声音</td><td>下拉选角色里的一个声音</td><td>无</td></tr></tbody></table><h2 id="_2-播放声音-喵-v" tabindex="-1">2. 播放声音 [喵 v] <a class="header-anchor" href="#_2-播放声音-喵-v" aria-label="Permalink to &quot;2. 播放声音 [喵 v]&quot;">​</a></h2><pre class="blocks"><code>播放声音 [喵 v]</code></pre><p>点了就放，脚本立刻往下走，声音在后台自己响。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>声音</td><td>下拉选角色里的一个声音</td><td>无</td></tr></tbody></table><h2 id="_3-停止所有声音" tabindex="-1">3. 停止所有声音 <a class="header-anchor" href="#_3-停止所有声音" aria-label="Permalink to &quot;3. 停止所有声音&quot;">​</a></h2><pre class="blocks"><code>停止所有声音</code></pre><p>把这个角色正在响的声音全部停掉。</p><p>没有参数。</p><h2 id="_4-将音量增加-10" tabindex="-1">4. 将音量增加 (10) <a class="header-anchor" href="#_4-将音量增加-10" aria-label="Permalink to &quot;4. 将音量增加 (10)&quot;">​</a></h2><pre class="blocks"><code>将音量增加 (10)</code></pre><p>音量在原来基础上加 10，写负数就变小。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>数值</td><td>加减多少；范围 0 ~ 100</td><td>无</td></tr></tbody></table><h2 id="_5-将音量设为-100" tabindex="-1">5. 将音量设为 (100)% <a class="header-anchor" href="#_5-将音量设为-100" aria-label="Permalink to &quot;5. 将音量设为 (100)%&quot;">​</a></h2><pre class="blocks"><code>将音量设为 (100)%</code></pre><p>音量直接设成指定大小，不用管原来是多少。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>音量</td><td>直接设定；0 = 静音，100 = 最大</td><td>%</td></tr></tbody></table><h2 id="_6-将-音调-v-音效增加-10" tabindex="-1">6. 将 [音调 v] 音效增加 (10) <a class="header-anchor" href="#_6-将-音调-v-音效增加-10" aria-label="Permalink to &quot;6. 将 [音调 v] 音效增加 (10)&quot;">​</a></h2><pre class="blocks"><code>将 [音调 v] 音效增加 (10)</code></pre><p>指定音效在原来基础上加 10——音调越高越尖，左右平衡越偏越靠一边。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>音效</td><td>下拉选&quot;音调&quot;或&quot;左右平衡&quot;</td><td>无</td></tr><tr><td>数值</td><td>加减多少</td><td>无</td></tr></tbody></table><h2 id="_7-将-音调-v-音效设为-10" tabindex="-1">7. 将 [音调 v] 音效设为 (10) <a class="header-anchor" href="#_7-将-音调-v-音效设为-10" aria-label="Permalink to &quot;7. 将 [音调 v] 音效设为 (10)&quot;">​</a></h2><pre class="blocks"><code>将 [音调 v] 音效设为 (10)</code></pre><p>指定音效直接设成指定值。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>单位</th></tr></thead><tbody><tr><td>音效</td><td>下拉选&quot;音调&quot;或&quot;左右平衡&quot;</td><td>无</td></tr><tr><td>数值</td><td>设成多少</td><td>无</td></tr></tbody></table><h2 id="_8-清除音效" tabindex="-1">8. 清除音效 <a class="header-anchor" href="#_8-清除音效" aria-label="Permalink to &quot;8. 清除音效&quot;">​</a></h2><pre class="blocks"><code>清除音效</code></pre><p>把音调、左右平衡全部恢复原样。</p><p>没有参数。</p><h2 id="_9-音量" tabindex="-1">9. 音量 <a class="header-anchor" href="#_9-音量" aria-label="Permalink to &quot;9. 音量&quot;">​</a></h2><pre class="blocks"><code>音量</code></pre><p>报告现在的音量，0 到 100。</p><p>没有参数。</p>',38)])])}const _=a(o,[["render",h]]);export{n as __pageData,_ as default};
